pub struct World {
    pub id: &'static str,
    pub gw: usize,
    pub gh: usize,
    pub map_width_km: f64,
    pub sea_level: f64,
    /// `riverFlowThresh(GW,GH)` as the reference computed it under this
    /// world's `state.mapWidthKm` -- captured rather than recomputed, because
    /// `UrbanWorld::flow_thresh` is a caller-supplied field on both sides.
    pub flow_thresh: f64,
    pub cell_km: f64,
    pub site_box_km: f64,
    pub water_near_km: f64,
    pub water_reach_km: f64,
}

/// The nominal shore column; the river's outlet is here.
fn q_of(gw: usize) -> usize {
    gw >> 2
}
/// The shoreline is **ragged**, on purpose. A vertical coast puts a whole
/// 5-cell column of sea in `_umSiteKindFromTerrain`'s 5x5 box or none at all,
/// so `seaFrac` could only be 0, 0.2, 0.4 ... and the `coast` arm
/// (`0.02 < seaFrac <= 0.15`) would be unreachable by construction.
fn shore_col(j: usize, gw: usize) -> i64 {
    q_of(gw) as i64 + ((j * 5) % 7) as i64 - 3
}
/// The trunk's centre row at column `i` -- a staircase, so it is not axis-aligned.
fn river_row(i: usize, gh: usize) -> usize {
    ((gh >> 1) + i / 8) % gh
}
/// The tributary's centre row; it meets the trunk near `i == gw*5/8`.
fn trib_row(i: usize, gh: usize) -> usize {
    ((gh >> 3) + ((i * 3) >> 3)) % gh
}
/// A triangle wave, so land stays inside `[0,1]` at either grid width.
fn tri(x: i64) -> i64 {
    let t = x % 1040;
    if t < 520 { t } else { 1040 - t }
}

fn height_millis(i: usize, j: usize, gw: usize, gh: usize) -> i64 {
    let s = shore_col(j, gw);
    if (i as i64) < s {
        return 200 + ((i * 7) % 100) as i64;
    }
    let mut v = 460 + tri((i as i64 - s) * 3) + ((j * 7) % 13) as i64;
    if (j as i64 - river_row(i, gh) as i64).abs() <= 1 {
        v -= 15;
    }
    if (j as i64 - trib_row(i, gh) as i64).abs() <= 1 {
        v -= 9;
    }
    v
}

const FLOW_HIGH: f32 = 5000.0;

/// Every raster the capture installed, rebuilt from the same integers.
pub struct Fixture {
    pub field: Vec<f32>,
    pub flow: Vec<f32>,
    pub temp: Vec<f32>,
    pub rain: Vec<f32>,
    pub carry: Vec<f32>,
    pub flood: Vec<f32>,
    pub wb: Vec<u8>,
    pub biome: Vec<u8>,
    pub order: Vec<i16>,
    pub recv: Vec<i32>,
    pub pots: ResourcePotentials,
    pub ways: Vec<Way>,
    pub coast_dt: Vec<f32>,
    pub polys: Vec<Vec<(f64, f64)>>,
}

fn pots_field<'a>(pots: &'a mut ResourcePotentials, key: &str) -> &'a mut Vec<f32> {
    match key {
        "copper" => &mut pots.copper,
        "tin" => &mut pots.tin,
        "iron" => &mut pots.iron,
        "gold" => &mut pots.gold,
        "salt" => &mut pots.salt,
        "timber" => &mut pots.timber,
        "lead" => &mut pots.lead,
        "silver" => &mut pots.silver,
        "clay" => &mut pots.clay,
        "buildstone" => &mut pots.buildstone,
        "flint" => &mut pots.flint,
        "obsidian" => &mut pots.obsidian,
        "gems" => &mut pots.gems,
        "sulfur" => &mut pots.sulfur,
        "alum" => &mut pots.alum,
        other => panic!("unknown resource key {other}"),
    }
}

fn zero_pots(n: usize) -> ResourcePotentials {
    let z = || vec![0.0f32; n];
    ResourcePotentials {
        copper: z(), tin: z(), iron: z(), gold: z(), salt: z(), timber: z(), lead: z(),
        silver: z(), clay: z(), buildstone: z(), flint: z(), obsidian: z(), gems: z(),
        sulfur: z(), alum: z(),
    }
}

/// The potentials the harness leaves installed while capturing profiles: a
/// `timber`/`clay` background -- the reason `resources_nearby` is non-empty --
/// plus **one** `iron` cell, so at least one profile's `resources` mean is
/// carried by a real deposit rather than by the background alone.
///
/// The iron cell is planted last, exactly as the harness does after zeroing
/// every key at the end of its ore sweep; dropping it made `resources[iron]`
/// `0.0` against a reference `0.0275862073` on the very first profile that
/// reaches it.
fn background_pots(w: &World) -> ResourcePotentials {
    let (gw, gh) = (w.gw, w.gh);
    let mut p = zero_pots(gw * gh);
    for j in 0..gh {
        for i in 0..gw {
            p.timber[j * gw + i] = ((i * 7 + j * 5) % 91) as f32 / 100.0;
            p.clay[j * gw + i] = ((i + j * 3) % 51) as f32 / 100.0;
        }
    }
    let (oi, oj) = (q_of(gw) + 14, river_row(q_of(gw) + 14, gh) + 2);
    if oi < gw && oj < gh {
        p.iron[oj * gw + oi] = 0.8;
    }
    p
}

pub fn build_world(w: &World) -> Fixture {
    let (gw, gh) = (w.gw, w.gh);
    let n = gw * gh;
    let mut f = Fixture {
        field: vec![0.0; n], flow: vec![0.0; n], temp: vec![0.0; n], rain: vec![0.0; n],
        carry: vec![0.0; n], flood: vec![0.0; n], wb: vec![0; n], biome: vec![0; n],
        order: vec![0; n], recv: vec![-1; n], pots: background_pots(w), ways: build_ways(w),
        coast_dt: Vec::new(), polys: Vec::new(),
    };
    let q = q_of(gw);
    for j in 0..gh {
        for i in 0..gw {
            let k = j * gw + i;
            f.field[k] = height_millis(i, j, gw, gh) as f32 / 1000.0;
            if (j == river_row(i, gh) || j == trib_row(i, gh)) && i >= q {
                f.flow[k] = FLOW_HIGH;
            }
            f.temp[k] = ((i * 5 + j * 3) % 41) as f32 - 6.0;
            f.rain[k] = ((i * 3 + j * 11) % 101) as f32 / 100.0;
            f.carry[k] = ((i * 13 + j * 5) % 61) as f32 / 100.0;
            f.flood[k] = ((i + j) % 17) as f32 / 100.0;
            f.wb[k] = if (f.field[k] as f64) < w.sea_level { 1 } else { 0 };
            f.biome[k] = if f.wb[k] == 1 { 0 } else { 1 + ((i * 2 + j) % 12) as u8 };
        }
    }
    // The river network: a trunk running west to the shore, plus a tributary.
    let put = |order: &mut [i16], recv: &mut [i32], i: usize, j: usize, ni: usize, nj: usize, ord: i16| {
        let k = j * gw + i;
        order[k] = ord;
        recv[k] = if ni < q { -1 } else { (nj * gw + ni) as i32 };
    };
    for i in (q..gw).rev() {
        put(&mut f.order, &mut f.recv, i, river_row(i, gh), i - 1, river_row(i - 1, gh), 3);
    }
    let join = (gw * 5) >> 3;
    for i in ((join + 1)..gw).rev() {
        let j = trib_row(i, gh);
        let nj = if i - 1 == join { river_row(i - 1, gh) } else { trib_row(i - 1, gh) };
        if f.order[j * gw + i] != 0 {
            continue;
        }
        put(&mut f.order, &mut f.recv, i, j, i - 1, nj, 1);
    }
    // The two derived fields the reference caches; each is the Rust port of
    // exactly the call `_umSiteProfile` makes, and a disagreement in either
    // shows up as a profile mismatch rather than hiding.
    f.coast_dt = civ_coast_dist_field(&f.field, gw, gh, w.sea_level);
    f.polys = trace_river_polylines(&f.order, &f.recv, gw, gh, 1);
    f
}

/// `civWays` as the reference stores it. The hidden way and the one-point way
/// are both skipped by `_civPlaceConnectedRoads`, which is why they are here.
fn build_ways(w: &World) -> Vec<Way> {
    let (gw, gh) = (w.gw, w.gh);
    let q = q_of(gw) as f64;
    let (gwf, ghf) = (gw as f64, gh as f64);
    let half = (gh >> 1) as f64;
    let mk = |pts: Vec<(f64, f64)>, t: WayType, km: f64, hidden: bool| Way {
        tid: 0, pts, brks: Vec::new(), km, name: String::new(), way_type: t,
        a_idx: 0, b_idx: 0, hidden,
    };
    vec![
        mk(vec![(q + 6.0, half), (q + 20.0, half), (gwf - 4.0, half + 6.0)], WayType::Highway, 120.0, false),
        mk(vec![(q + 6.0, half), (q + 6.0, 4.0)], WayType::Regional, 60.0, false),
        mk(vec![(q + 6.0, half), (2.0, ghf - 3.0)], WayType::Track, 40.0, false),
        mk(vec![(q + 6.0, half), (gwf - 2.0, 2.0)], WayType::Road, 90.0, true),
        mk(vec![(q + 30.0, 8.0)], WayType::Road, 5.0, false),
        mk(vec![(gwf - 6.0, ghf - 6.0), (q + 2.0, ghf - 6.0)], WayType::Regional, 70.0, false),
    ]
}

fn urban_world<'a>(w: &World, f: &'a Fixture) -> UrbanWorld<'a> {
    UrbanWorld {
        field: &f.field, flow: &f.flow, water_bodies: &f.wb, order: Some(&f.order),
        river_polys: &f.polys, gw: w.gw, gh: w.gh, sea_level: w.sea_level,
        map_width_km: w.map_width_km, flow_thresh: w.flow_thresh, world_seed: 12345,
    }
}

fn find_world(id: &str) -> &'static World {
    WORLDS.iter().find(|w| w.id == id).unwrap_or_else(|| panic!("no world {id}"))
}

/// The reference's `p.kind` string as this port's enum. `_umWallSpec`'s
/// `fortress` rung has no [`SettlementKind`] variant -- `military.rs` says so
/// -- so the capture never emits one, and this panics rather than silently
/// picking a neighbouring rank if that ever changes.
fn settlement_kind(kind: &str) -> SettlementKind {
    match kind {
        "metropolis" => SettlementKind::Metropolis,
        "capital" => SettlementKind::Capital,
        "city" => SettlementKind::City,
        "town" => SettlementKind::Town,
        "village" => SettlementKind::Village,
        "hamlet" => SettlementKind::Hamlet,
        other => panic!("captured kind {other:?} has no SettlementKind variant"),
    }
}

