/// Bit-exact: these are captured `f64` bit patterns, not tolerances. The one
/// place a tolerance would be right is a value this port deliberately computes
/// differently, and there is none here.
#[track_caller]
fn eq(what: &str, got: f64, want: f64) {
    assert!(
        got.to_bits() == want.to_bits() || (got.is_nan() && want.is_nan()),
        "{what}: got {got:?} (0x{:016x}), reference {want:?} (0x{:016x})",
        got.to_bits(),
        want.to_bits()
    );
}

#[test]
fn the_fixture_is_not_degenerate() {
    // The silently-empty-golden gate, re-run on this side: four subsystems in
    // this port have been bitten by a golden that passed over nothing.
    assert_eq!(WORLDS.len(), 2, "both grid sizes must be present");
    assert_eq!(AGES.len(), 22);
    assert_eq!(HARBOURS.len(), 12);
    assert_eq!(RAYS.len(), 10);
    assert_eq!(KINDS.len(), 241);
    assert_eq!(ORES.len(), 22);
    assert_eq!(PROFILES.len(), 18);
    for w in WORLDS {
        let f = build_world(w);
        let n = w.gw * w.gh;
        assert_eq!(f.field.len(), n);
        assert!(f.field.iter().any(|&h| (h as f64) < w.sea_level), "{}: no sea", w.id);
        assert!(f.field.iter().any(|&h| (h as f64) >= w.sea_level), "{}: no land", w.id);
        assert!(f.flow.iter().any(|&v| v > 0.0), "{}: no river flow", w.id);
        assert!(f.polys.len() >= 2, "{}: expected >=2 traced stems, got {}", w.id, f.polys.len());
        assert!(f.coast_dt.iter().any(|&d| d == 0.0), "{}: coast DT never reaches the shore", w.id);
        assert!(f.coast_dt.iter().any(|&d| d > 0.0), "{}: coast DT is all zero", w.id);
        assert!(f.biome.iter().any(|&b| b == 0) && f.biome.iter().any(|&b| b != 0), "{}: biome raster is uniform", w.id);
    }
    // Both arms of `_umWaterReachKm`'s max, from the captured values alone.
    assert!(WORLDS.iter().any(|w| eqf(w.water_reach_km, w.water_near_km)), "no world reached the near-km arm");
    assert!(WORLDS.iter().any(|w| !eqf(w.water_reach_km, w.water_near_km)), "no world reached the cell arm");
    // And the three site kinds the capture gate requires.
    for k in ["coast", "river", "landlocked"] {
        assert!(KINDS.iter().any(|c| c.kind == k), "no captured site kind is '{k}'");
    }
    assert!(ORES.iter().any(|c| c.bearing.is_some()), "no ore bearing was found");
    assert!(ORES.iter().any(|c| c.bearing.is_none()), "no ore bearing was absent");
    assert!(PROFILES.iter().any(|c| c.river_order > 0.0), "no profile has a river");
    assert!(PROFILES.iter().any(|c| c.river_order == 0.0), "no profile is riverless");
    assert!(PROFILES.iter().any(|c| c.road_count > 0), "no profile has roads");
    assert!(PROFILES.iter().any(|c| c.road_count == 0), "no profile is roadless");
    assert!(PROFILES.iter().any(|c| !c.resources_nearby.is_empty()), "no profile has nearby resources");
    assert!(PROFILES.iter().any(|c| c.coast_dist_km.is_finite()), "no profile has a finite coast distance");
}

fn eqf(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits()
}

#[test]
fn site_box_ladder_matches_reference() {
    for w in WORLDS {
        eq(&format!("{}: _umSiteBoxKm", w.id), um_site_box_km(), w.site_box_km);
        eq(&format!("{}: _umWaterNearKm", w.id), um_water_near_km(), w.water_near_km);
        eq(
            &format!("{}: _umWaterReachKm", w.id),
            um_water_reach_km(w.gw, w.map_width_km),
            w.water_reach_km,
        );
    }
}

