/// The capture calls `_umRayBoxExit(dx,dy,UME.SITE_WM,UME.SITE_HM)`, so the
/// box passed here is [`SITE_WM`]/[`SITE_HM`] and **not** the literals `1700`
/// / `1250`. That is the difference between a live and a dead assertion:
/// mutating `SITE_HM` to `1251.0` survived the whole matrix while these were
/// literals -- nothing else in the golden can see it, because
/// `_umSiteBoxKm` is `max(SITE_WM,SITE_HM)/1000` and the buildable-area
/// lattice moves by <0.0002 cells for a one-metre change in box height.
#[test]
fn ray_box_exit_matches_reference() {
    assert_eq!((SITE_WM, SITE_HM), (1700.0, 1250.0), "UME.SITE_WM/SITE_HM as the capture read them");
    for c in RAYS {
        let p = um_ray_box_exit(c.dx, c.dy, SITE_WM, SITE_HM);
        eq(&format!("{}.x", c.name), p.x, c.x);
        eq(&format!("{}.y", c.name), p.y, c.y);
    }
}

#[test]
fn site_kind_matches_reference() {
    for c in KINDS {
        let w = find_world(c.world);
        let f = build_world(w);
        let uw = urban_world(w, &f);
        assert_eq!(
            um_site_kind_from_terrain(&uw, c.px, c.py),
            c.kind,
            "{} ({}, {})",
            c.world,
            c.px,
            c.py
        );
    }
}

#[test]
fn ore_bearing_matches_reference() {
    for c in ORES {
        let w = find_world(c.world);
        let mut pots = zero_pots(w.gw * w.gh);
        if let Some(key) = c.key {
            let (x, y) = (c.px as i64 + c.dx, c.py as i64 + c.dy);
            if x >= 0 && y >= 0 && x < w.gw as i64 && y < w.gh as i64 {
                pots_field(&mut pots, key)[y as usize * w.gw + x as usize] = c.v as f32;
            }
        }
        let got = um_ore_bearing(&pots, w.gw, w.gh, c.px, c.py, c.orient);
        match (got, c.bearing) {
            (Some(g), Some(want)) => eq(c.name, g, want),
            (None, None) => {}
            (g, want) => panic!("{}/{}: got {g:?}, reference {want:?}", c.world, c.name),
        }
    }
}

#[test]
fn site_profile_matches_reference() {
    for c in PROFILES {
        let w = find_world(c.world);
        let f = build_world(w);
        let uw = urban_world(w, &f);
        // The one input the reference resolves for itself and this port takes
        // from its caller -- captured from `_umInferWalls` and re-derived here,
        // so a drift in `um_wall_spec` fails as loudly as a drift in the profile.
        let place = WallPlace {
            kind: settlement_kind(c.kind),
            pop: c.pop,
            // `p.umWalls` / `p.umAge` are both absent on every settlement the
            // reference builds until something sets one, which is the value
            // the capture ran under.
            walls_override: None,
            age_override: None,
            specialisation: None,
            fortified_trait: false,
            relative_elevation: cartalith_civ::military::civ_relative_elevation(
                &f.field, w.gw, w.gh, w.sea_level, c.px, c.py,
            ),
        };
        assert_eq!(um_infer_walls(&place), c.walled, "{}/{}: walled", c.world, c.name);
        let e = SiteProfileWorld {
            coast_dt: &f.coast_dt,
            flood: &f.flood,
            biome: &f.biome,
            temp: &f.temp,
            rain: &f.rain,
            carry_k: &f.carry,
            res: &f.pots,
            ways: &f.ways,
            world_wrap: false,
            walled: c.walled,
        };
        let sp = um_site_profile(&uw, &e, c.px, c.py)
            .unwrap_or_else(|| panic!("{}/{}: um_site_profile returned None", c.world, c.name));
        let at = |field: &str| format!("{}/{}: {field}", c.world, c.name);
        assert_eq!(sp.site_kind, c.site_kind, "{}", at("site_kind"));
        eq(&at("elevation"), sp.elevation, c.elevation);
        eq(&at("elev_n"), sp.elev_n, c.elev_n);
        eq(&at("slope_n"), sp.slope_n, c.slope_n);
        match (sp.aspect, c.aspect) {
            (Some(g), Some(want)) => eq(&at("aspect"), g, want),
            (None, None) => {}
            (g, want) => panic!("{}: got {g:?}, reference {want:?}", at("aspect")),
        }
        eq(&at("local_relief"), sp.local_relief, c.local_relief);
        eq(&at("visibility"), sp.visibility, c.visibility);
        eq(&at("coast_dist_km"), sp.coast_dist_km, c.coast_dist_km);
        eq(&at("river_dist_km"), sp.river_dist_km, c.river_dist_km);
        eq(&at("river_order"), sp.river_order, c.river_order);
        eq(&at("river_width_m"), sp.river_width_m, c.river_width_m);
        assert_eq!(sp.confluence, c.confluence, "{}", at("confluence"));
        eq(&at("floodplain"), sp.floodplain, c.floodplain);
        assert_eq!(sp.road_count, c.road_count, "{}", at("road_count"));
        assert_eq!(sp.road_types, c.road_types, "{}", at("road_types"));
        match &sp.resources {
            Some(m) => {
                assert_eq!(m.len(), c.resources.len(), "{}", at("resources.len"));
                for &(k, want) in c.resources {
                    eq(&at(&format!("resources[{k}]")), *m.get(k).unwrap_or_else(|| panic!("{}", at(k))), want);
                }
            }
            None => assert!(c.resources.is_empty(), "{}", at("resources")),
        }
        assert_eq!(sp.resources_nearby, c.resources_nearby, "{}", at("resources_nearby"));
        assert_eq!(sp.biome, c.biome, "{}", at("biome"));
        eq(&at("temp_c"), sp.temp_c, c.temp_c);
        eq(&at("rain"), sp.rain, c.rain);
        eq(&at("carry_k"), sp.carry_k, c.carry_k);
        eq(&at("defensibility"), sp.defensibility, c.defensibility);
        eq(&at("buildable_frac"), sp.buildable_frac, c.buildable_frac);
    }
}

/// The 15 keys `_civPlaceResourceContext` sums over -- pinned here because
/// the captured `resources` maps are keyed by them and a reorder or a rename
/// would otherwise pass silently.
#[test]
fn resource_keys_match_the_captured_maps() {
    let first = PROFILES
        .iter()
        .find(|c| !c.resources.is_empty())
        .expect("no profile captured a resource map");
    assert_eq!(first.resources.len(), CIV_RESOURCE_KEYS.len());
    for &(k, _) in first.resources {
        assert!(CIV_RESOURCE_KEYS.contains(&k), "captured key {k} is not in CIV_RESOURCE_KEYS");
    }
}

